class.description:
Draws progress bars attached to [CanvasItem]s without one node per bar. Each bar is a canvas item that is a child of its parent's canvas item, so it moves with the parent and is hidden with it at no per-frame cost. A bar is redrawn only when its ratio, visibility, offset or [ProgressBarStyle] changes; bars that share [StyleBox]es are batched by the renderer. Only bars whose style uses [constant ProgressBarStyle.FOLLOW_MODE_POSITION_ONLY] are updated once per frame.
When a parent is deleted, the server frees its bars on the next frame. Freeing them yourself with [method bar_free] (for example in [method Node._exit_tree]) is still the cleanest way.
The returned bar [RID] is the [RID] of the bar's canvas item: [RenderingServer] calls such as [method RenderingServer.canvas_item_set_z_index] work on it, but never free it with [method RenderingServer.free_rid]. Call the server from the main thread.
[codeblocks]
[gdscript]
@export var bar_style: ProgressBarStyle
var health_bar: RID

func _ready():
    health_bar = ProgressBarServer.bar_create(self, bar_style)

func _exit_tree():
    ProgressBarServer.bar_free(health_bar)

func take_damage(health, max_health):
    ProgressBarServer.bar_set_ratio(health_bar, health / max_health)
[/gdscript]
[csharp]
[Export]
public ProgressBarStyle BarStyle { get; set; }
private Rid _healthBar;

public override void _Ready()
{
    _healthBar = ProgressBarServer.BarCreate(this, BarStyle);
}

public override void _ExitTree()
{
    ProgressBarServer.BarFree(_healthBar);
}

public void TakeDamage(float health, float maxHealth)
{
    ProgressBarServer.BarSetRatio(_healthBar, health / maxHealth);
}
[/csharp]
[/codeblocks]
